    private static void RequireBookSchema(IDataSource source)
    {
        var schema=source.GetEntityStructure(new EntityStructure{EntityName=CompanyBookTable,DatasourceEntityName=CompanyBookTable},true);var keys=schema?.Fields?.Where(field=>field.IsKey).ToArray();
        if(schema?.EntityName!=CompanyBookTable || keys is not {Length:1} || keys[0].FieldName!=CompanyBookTable+"_ID" || keys[0].Fieldtype!=typeof(string).FullName || keys[0].AllowDBNull || Math.Max(keys[0].Size,keys[0].Size1)<32)throw new InvalidOperationException("Review the original book identity through the PRODUCTION Beep migration.");
        foreach(var (name,size) in new[]{("OWNER_TENANT_ID",128),("OWNER_COMPANY_BA_ID",128),("BOOK_ID",128),("BOOK_NAME",256),("FUNCTIONAL_CURRENCY",16),("ROUNDING_POLICY",32),("CALENDAR_ID",128),("TIME_ZONE_ID",128),("CONFIGURATION_JSON",CompanyLedgerBookConfigurationProof.MaximumLength)}){var fields=schema?.Fields?.Where(field=>field.FieldName==name).ToArray();if(fields is not {Length:1} || fields[0].Fieldtype!=typeof(string).FullName || fields[0].AllowDBNull || Math.Max(fields[0].Size,fields[0].Size1)<size)throw new InvalidOperationException("The required bounded native company book facts/receipt are unconfirmed.");}
        var precision=schema?.Fields?.Where(field=>field.FieldName=="CURRENCY_DECIMALS").ToArray();if(precision is not {Length:1} || precision[0].Fieldtype!=typeof(int).FullName || precision[0].AllowDBNull)throw new InvalidOperationException("The explicit native book currency precision is unconfirmed.");
    }
