        async Task Guard(){await requireAuthority();if(await _resolveConnection()!=connection || !ReferenceEquals(_editor.GetDataSource(connection),source))throw new InvalidOperationException("The original book binding changed.");RequireBookSchema(source);}
        async Task<COMPANY_LEDGER_BOOK?> Capture(){await Guard();var repo=new PPDMGenericRepository(_editor,_commonColumnHandler,_defaults,_metadata,typeof(COMPANY_LEDGER_BOOK),connection,CompanyBookTable);var rows=(await repo.GetAsync([new(){FieldName="COMPANY_LEDGER_BOOK_ID",Operator="=",FilterValue=id}]))?.ToArray();await Guard();if(rows is null || rows.Length>1 || rows.Any(row=>row is not COMPANY_LEDGER_BOOK))throw new InvalidOperationException("The original book configuration is unavailable or ambiguous.");var row=rows.SingleOrDefault() as COMPANY_LEDGER_BOOK;if(row is null)return null;var receipt=CompanyLedgerBookConfigurationProof.Require(row);if(receipt.Command.Company!=company || receipt.Command.ActorUserId!=actor)throw new UnauthorizedAccessException("Only the original book producer may recover its private request.");return CompanyInventorySourceReview.Copy(row);}
        var initial=await Capture();var closing=await Capture();await Guard();if(JsonSerializer.Serialize(initial)!=JsonSerializer.Serialize(closing))throw new InvalidOperationException("The original book changed during recovery.");return closing;
